"""Stock levels, the buy list, history and safe appending of movements."""

from collections import namedtuple

from .movements import Movement, first_negative, ordered

StockRow = namedtuple("StockRow", "sku name onhand status")
LowRow = namedtuple("LowRow", "sku onhand reorder buy")
HistoryRow = namedtuple("HistoryRow", "date delta balance note")


def stock_levels(catalog, movements):
    """Dict of SKU to on-hand quantity for every product in the catalogue."""
    levels = dict.fromkeys(catalog, 0)
    for m in movements:
        if m.sku in levels:
            levels[m.sku] += m.quantity
    return levels


def status_of(onhand, reorder):
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def stock_report(catalog, movements):
    levels = stock_levels(catalog, movements)
    return [
        StockRow(sku, catalog[sku].name, levels[sku], status_of(levels[sku], catalog[sku].reorder))
        for sku in sorted(catalog)
    ]


def low_report(catalog, movements):
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        reorder = catalog[sku].reorder
        if status_of(levels[sku], reorder) != "ok":
            rows.append(LowRow(sku, levels[sku], reorder, max(1, 2 * reorder - levels[sku])))
    return rows


def history(sku, movements):
    """Movements of ``sku`` in counting order with the running balance."""
    rows = []
    balance = 0
    for m in ordered(movements):
        if m.sku == sku:
            balance += m.quantity
            rows.append(HistoryRow(m.date, "%+d" % m.quantity, balance, m.note))
    return rows


class Refused(Exception):
    """A request that breaks a rule; nothing was changed."""


def append_candidate(catalog, movements, date, sku, quantity, note):
    """Validate a new movement against every rule; return it or raise Refused.

    ``quantity`` is the signed quantity. ``movements`` is the existing list.
    """
    sku = sku.upper()
    if sku not in catalog:
        raise Refused("unknown SKU %s" % sku)
    if "\n" in note or "\r" in note:
        raise Refused("note must not contain a line break")
    note = note.strip()
    if quantity == 0:
        raise Refused("quantity must not be zero")
    candidate = Movement(date, sku, quantity, note, len(movements) + 1_000_000_000)
    bad = first_negative(list(movements) + [candidate])
    if bad is not None:
        m, balance = bad
        if m is candidate:
            raise Refused("stock of %s would go below zero (%d)" % (sku, balance))
        raise Refused(
            "stock of %s would go below zero (%d) at movements line %d"
            % (m.sku, balance, m.line)
        )
    return candidate


def format_movement(m):
    text = "%s %s %+d" % (m.date.isoformat(), m.sku, m.quantity)
    if m.note:
        text += " " + m.note
    return text
