"""Shipping what the shelves can cover, and order status."""

from .movements import Movement, ordered
from .orders import Order


def order_note(order):
    return "order " + order.id


def shipped_so_far(order, movements):
    """Dict of SKU to units already shipped for ``order`` (capped at ordered)."""
    note = order_note(order)
    out = {}
    for m in movements:
        if m.note == note and m.quantity < 0:
            out[m.sku] = out.get(m.sku, 0) - m.quantity
    return {sku: min(out.get(sku, 0), qty) for sku, qty in order.lines}


def available_on(movements, sku, date):
    """Most that can leave on ``date`` without any balance going negative."""
    balance = 0
    later = []
    for m in ordered(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        if m.date > date:
            later.append(balance)
    on_date = balance - sum(m.quantity for m in movements if m.sku == sku and m.date > date)
    return min([on_date] + later)


def status_of(order, shipped):
    owed = [qty - shipped.get(sku, 0) for sku, qty in order.lines]
    if all(o == 0 for o in owed):
        return "complete"
    if all(shipped.get(sku, 0) == 0 for sku, _ in order.lines):
        return "open"
    return "partial"


def fulfil(order, date, movements):
    """Work out a shipment of ``order`` on ``date``.

    Returns ``(rows, new_movements, status)`` where rows are
    ``(sku, shipped_now, backordered)``. Nothing is written here.
    """
    current = list(movements)
    shipped = shipped_so_far(order, current)
    new = []
    rows = []
    for sku, qty in order.lines:
        owed = qty - shipped[sku]
        ship = max(0, min(owed, available_on(current, sku, date)))
        if ship > 0:
            m = Movement(date, sku, -ship, order_note(order))
            current.append(m)
            new.append(m)
            shipped[sku] += ship
        rows.append((sku, ship, qty - shipped[sku]))
    return rows, new, status_of(order, shipped)


def shipped_order(order, shipped):
    """The order restricted to shipped quantities, or None when nothing shipped."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped.get(sku, 0) > 0]
    if not lines:
        return None
    return Order(order.id, order.date, order.customer, lines)
EOF

