        invoiced = price_order(billed, data.catalog).total if billed else Decimal("0.00")
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": fulfilment.status_of(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped.values()),
                "quoted": money(price_order(order, data.catalog).total),
                "invoiced": money(invoiced),
            }
        )
