    if fmt == "json":
        return dump(rows)
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.DictWriter(
            buffer,
            ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"],
            lineterminator="\n",
        )
        writer.writeheader()
        writer.writerows(rows)
        return buffer.getvalue()
    return lines_out(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"], r["date"], r["customer"], r["status"],
            r["shipped"], r["ordered"], r["quoted"], r["invoiced"],
        )
