    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move(1),
    "ship": cmd_move(-1),
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def run(argv):
    command, positionals, options, directory = parse_args(argv)
    data = Data(directory, COMMANDS[command][2])
    return HANDLERS[command](data, positionals, options)


# --------------------------------------------------------------------- main


def _stderr(message):
    data = ("stockroom: %s\n" % message).encode("utf-8", "backslashreplace")
    try:
        stream = getattr(sys.stderr, "buffer", None)
        if stream is not None:
            stream.write(data)
            stream.flush()
        else:
            sys.stderr.write(data.decode("utf-8"))
    except (OSError, ValueError):
        pass


def _quiet_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    if not text:
        return
    try:
        stream = getattr(sys.stdout, "buffer", None)
        if stream is not None:
            stream.write(text.encode("utf-8"))
        else:
            sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _quiet_stdout()


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        text = run(list(argv))
    except CliExit as exc:
        _stderr(exc.message)
        return exc.code
    _emit(text)
    return 0
